'use client';

import { useCallback, useId, useRef, type CSSProperties, type JSX, type ReactNode } from 'react';
import {
  Dialog as RACDialog,
  Heading,
  Modal,
  ModalOverlay,
  PopoverContext,
  useSlottedContext,
  type DialogProps as RACDialogProps,
} from 'react-aria-components';
import { IconX } from '@tabler/icons-react';
import { Button } from './button';
import styles from './sheet.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

/** Overlays portal to <body>: copy the trigger's ThemeScope attributes (and dir/lang) onto the overlay root. */
const SCOPE_ATTRS = ['data-strata-theme', 'data-strata-scheme', 'data-strata-density'] as const;
function mirrorScope(overlay: HTMLElement, source: Element | null | undefined): void {
  if (!source || overlay.contains(source)) return;
  for (const name of SCOPE_ATTRS) {
    // Look each attribute up on its own: a single-tenant app themes :root and scopes only the scheme.
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value) overlay.setAttribute(name, value);
  }
  for (const name of ['dir', 'lang']) {
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value) overlay.setAttribute(name, value);
  }
}

export interface SheetRenderProps {
  /** Closes the sheet. */
  close: () => void;
}

export interface SheetProps extends Omit<RACDialogProps, 'children' | 'className' | 'style'> {
  /** Edge the panel slides in from. Logical: `end` is the right edge in LTR and the left edge in RTL. */
  side?: 'start' | 'end' | 'top' | 'bottom';
  /** Heading at the top of the panel; also its accessible name. */
  title: ReactNode;
  /** Supporting text under the title. */
  description?: ReactNode;
  /** Panel content, or a function that receives `{ close }`. Scrolls independently of header and footer. */
  children?: ReactNode | ((opts: SheetRenderProps) => ReactNode);
  /** Actions pinned to the bottom of the panel. Also accepts a function that receives `{ close }`. */
  footer?: ReactNode | ((opts: SheetRenderProps) => ReactNode);
  /** Whether clicking the backdrop closes the sheet. */
  isDismissable?: boolean;
  /** Whether Escape is ignored. */
  isKeyboardDismissDisabled?: boolean;
  /** Controlled open state — only when the sheet is not inside a DialogTrigger. */
  isOpen?: boolean;
  /** Initial open state — only when the sheet is not inside a DialogTrigger. */
  defaultOpen?: boolean;
  /** Called when the open state changes — only when the sheet is not inside a DialogTrigger. */
  onOpenChange?: (isOpen: boolean) => void;
  /** Class for the panel. */
  className?: string;
  /** Style for the panel. */
  style?: CSSProperties;
}

/**
 * A modal panel attached to an edge of the viewport — for filters, details and secondary tasks that keep the page
 * in context. Use inside a DialogTrigger, or control it with `isOpen`/`onOpenChange`.
 */
export function Sheet({
  side = 'end',
  title,
  description,
  children,
  footer,
  isDismissable = true,
  isKeyboardDismissDisabled,
  isOpen,
  defaultOpen,
  onOpenChange,
  className,
  style,
  ...props
}: SheetProps): JSX.Element {
  const descriptionId = useId();
  const triggerRef = useSlottedContext(PopoverContext)?.triggerRef;
  const anchorRef = useRef<HTMLSpanElement>(null);
  const overlayRef = useCallback(
    (node: HTMLDivElement | null) => {
      if (node) mirrorScope(node, triggerRef?.current ?? anchorRef.current ?? document.activeElement);
    },
    [triggerRef],
  );

  return (
    <>
      {!triggerRef && <span ref={anchorRef} hidden />}
      <ModalOverlay
        ref={overlayRef}
        className={styles.overlay}
        isDismissable={isDismissable}
        isKeyboardDismissDisabled={isKeyboardDismissDisabled}
        isOpen={isOpen}
        defaultOpen={defaultOpen}
        onOpenChange={onOpenChange}
      >
        <Modal className={cx(styles.panel, className)} style={style} data-side={side}>
          <RACDialog
            {...props}
            aria-describedby={cx(description != null && descriptionId, props['aria-describedby']) || undefined}
            className={styles.dialog}
          >
            {({ close }) => (
              <>
                <header className={styles.header}>
                  <Heading slot="title" level={2} className={styles.title}>
                    {title}
                  </Heading>
                  {description != null && (
                    <p id={descriptionId} className={styles.description}>
                      {description}
                    </p>
                  )}
                </header>
                <div className={styles.body}>{typeof children === 'function' ? children({ close }) : children}</div>
                {footer != null && (
                  <footer className={styles.footer}>{typeof footer === 'function' ? footer({ close }) : footer}</footer>
                )}
                <Button variant="ghost" size="icon" aria-label="Close" onPress={close} className={styles.close}>
                  <IconX aria-hidden stroke={1.75} />
                </Button>
              </>
            )}
          </RACDialog>
        </Modal>
      </ModalOverlay>
    </>
  );
}

/* Backdrop. Portalled to <body>, so it re-applies the ThemeScope base (font, colour, box model). */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  box-sizing: border-box;
  /* Dim what's behind by a fixed amount. A colour tint can't do this in both schemes: every surface token is
     already near the page colour in dark schemes, and light-dark() gets mangled by Lightning CSS pipelines. */
  -webkit-backdrop-filter: brightness(0.55);
  backdrop-filter: brightness(0.55);
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-normal);
  color: var(--strata-color-text-default);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.overlay *,
.overlay *::before,
.overlay *::after {
  box-sizing: border-box;
}

.panel {
  position: fixed;
  display: flex;
  flex-direction: column;
  background: var(--strata-color-surface-raised);
  box-shadow: var(--strata-shadow-overlay);
  outline: none;
}
.panel[data-side='start'],
.panel[data-side='end'] {
  --sheet-from: 100% 0;
  inset-block: 0;
  inline-size: min(calc(var(--strata-space-16) * 6.5), 90%);
}
.panel[data-side='end'] {
  inset-inline-end: 0;
  border-inline-start: 1px solid var(--strata-color-border-default);
}
.panel[data-side='start'] {
  --sheet-from: -100% 0;
  inset-inline-start: 0;
  border-inline-end: 1px solid var(--strata-color-border-default);
}
/* The overlay root always carries the copied dir. Kept apart from the :dir() rules (which some CSS pipelines
   rewrite to :lang()) so an unsupported selector can't drop them. */
.overlay[dir='rtl'] .panel[data-side='end'] {
  --sheet-from: -100% 0;
}
.overlay[dir='rtl'] .panel[data-side='start'] {
  --sheet-from: 100% 0;
}
.panel[data-side='end']:dir(rtl) {
  --sheet-from: -100% 0;
}
.panel[data-side='start']:dir(rtl) {
  --sheet-from: 100% 0;
}
.panel[data-side='top'],
.panel[data-side='bottom'] {
  inset-inline: 0;
  max-block-size: 85dvh;
}
.panel[data-side='top'] {
  --sheet-from: 0 -100%;
  inset-block-start: 0;
  border-block-end: 1px solid var(--strata-color-border-default);
  border-end-start-radius: var(--strata-radius-container);
  border-end-end-radius: var(--strata-radius-container);
}
.panel[data-side='bottom'] {
  --sheet-from: 0 100%;
  inset-block-end: 0;
  border-block-start: 1px solid var(--strata-color-border-default);
  border-start-start-radius: var(--strata-radius-container);
  border-start-end-radius: var(--strata-radius-container);
  padding-block-end: env(safe-area-inset-bottom, 0);
}

.dialog {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  gap: var(--strata-space-4);
  min-block-size: 0;
  padding-block: var(--strata-card-inset);
  outline: none;
}

.header {
  display: grid;
  gap: var(--strata-space-1);
  padding-inline: var(--strata-card-inset);
  padding-inline-end: calc(var(--strata-card-inset) + var(--strata-control-height));
}
.title {
  margin: 0;
  font-family: var(--strata-font-heading);
  font-size: var(--strata-font-size-lg);
  font-weight: var(--strata-font-weight-semibold);
  line-height: var(--strata-line-height-snug);
  letter-spacing: var(--strata-font-heading-tracking);
  color: var(--strata-color-text-default);
}
.description {
  margin: 0;
  font-size: var(--strata-font-size-sm);
  color: var(--strata-color-text-subtle);
}

.body {
  display: grid;
  align-content: start;
  gap: var(--strata-field-gap);
  flex: 1 1 auto;
  min-block-size: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--strata-space-1) var(--strata-card-inset);
  margin-block: calc(var(--strata-space-1) * -1);
}

.footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--strata-space-2);
  padding-inline: var(--strata-card-inset);
}

.close {
  position: absolute;
  inset-block-start: calc(var(--strata-card-inset) - var(--strata-space-2));
  inset-inline-end: calc(var(--strata-card-inset) - var(--strata-space-2));
  color: var(--strata-color-text-subtle);
}

@media (prefers-reduced-motion: no-preference) {
  .overlay[data-entering] {
    animation: fade var(--strata-motion-duration-normal) var(--strata-motion-easing);
  }
  .overlay[data-exiting] {
    animation: fade var(--strata-motion-duration-fast) var(--strata-motion-easing) reverse;
  }
  .panel[data-entering] {
    animation: slide var(--strata-motion-duration-normal) var(--strata-motion-easing);
  }
  .panel[data-exiting] {
    animation: slide var(--strata-motion-duration-fast) var(--strata-motion-easing) reverse;
  }
}

@keyframes fade {
  from {
    opacity: 0;
  }
}
@keyframes slide {
  from {
    translate: var(--sheet-from);
  }
}
